+				continue
+			}
+			pidListenPorts[pid] = append(pidListenPorts[pid], *portStat)
+		}
+	}
+
+	for pid, loadedFiles := range pidLoadedFiles {
+		pkgNames, err := getOwnerPkgs(loadedFiles)
+		if err != nil {
+			o.log.Debugf("Failed to get package name by file path: %v, err: %s", pkgNames, err)
+			continue
+		}
+
+		uniq := map[string]struct{}{}
+		for _, name := range pkgNames {
+			uniq[name] = struct{}{}
+		}
+
+		procName := ""
+		if _, ok := pidNames[pid]; ok {
+			procName = pidNames[pid]
+		}
+		proc := models.AffectedProcess{
+			PID:             pid,
+			Name:            procName,
+			ListenPortStats: pidListenPorts[pid],
+		}
+
+		for name := range uniq {
+			p, ok := o.Packages[name]
+			if !ok {
+				continue
+			}
+			p.AffectedProcs = append(p.AffectedProcs, proc)
+			o.Packages[name] = p
+		}
+	}
+	return nil
+}
